<?php
require_once __DIR__ . '/../includes/auth.php'; require_login('admin'); $admin = current_user();
if ($_SERVER['REQUEST_METHOD'] === 'POST') { verify_csrf(); $id = (int) ($_POST['id'] ?? 0); $status = $_POST['status'] ?? ''; $remarks = trim($_POST['admin_remarks'] ?? ''); if (in_array($status, ['approved', 'rejected'], true) && $id) { $statement = db()->prepare('UPDATE leave_applications SET status = ?, admin_remarks = ?, reviewed_by = ?, reviewed_at = NOW() WHERE id = ? AND status = \'pending\''); $statement->execute([$status, $remarks, $admin['id'], $id]); $item = db()->prepare('SELECT user_id, days FROM leave_applications WHERE id = ?'); $item->execute([$id]); $item = $item->fetch(); if ($item) { $notice = db()->prepare('INSERT INTO notifications (user_id, title, message) VALUES (?, ?, ?)'); $notice->execute([$item['user_id'], 'Leave request ' . $status, 'Your ' . $item['days'] . '-day leave request was ' . $status . '.']); } flash('success', 'Request ' . $status . ' successfully.'); } header('Location: ' . base_url('admin/leaves.php')); exit; }
$filter = $_GET['status'] ?? 'all'; $where = $filter !== 'all' && in_array($filter, ['pending','approved','rejected'], true) ? 'WHERE la.status = ' . db()->quote($filter) : '';
$requests = db()->query("SELECT la.*, u.full_name, u.employee_code, u.department, lt.name AS leave_type FROM leave_applications la JOIN users u ON u.id = la.user_id JOIN leave_types lt ON lt.id = la.leave_type_id $where ORDER BY FIELD(la.status, 'pending', 'approved', 'rejected'), la.created_at DESC");
$pageTitle = 'Leave requests'; require __DIR__ . '/../includes/header.php';
?><div class="page-content"><div class="detail-heading"><div><span class="eyebrow">Administration / Time away</span><h2>Leave requests</h2><p class="muted mb-0">Review requests and keep decisions transparent.</p></div></div><div class="filter-bar"><a class="btn <?= $filter === 'all' ? 'btn-primary' : 'btn-outline-dark' ?>" href="?status=all">All</a><a class="btn <?= $filter === 'pending' ? 'btn-primary' : 'btn-outline-dark' ?>" href="?status=pending">Pending</a><a class="btn <?= $filter === 'approved' ? 'btn-primary' : 'btn-outline-dark' ?>" href="?status=approved">Approved</a><a class="btn <?= $filter === 'rejected' ? 'btn-primary' : 'btn-outline-dark' ?>" href="?status=rejected">Rejected</a></div><section class="panel"><table class="table"><thead><tr><th>Employee</th><th>Request</th><th>Dates</th><th>Reason</th><th>Status</th><th>Action</th></tr></thead><tbody><?php while ($item = $requests->fetch()): ?><tr><td><strong><?= e($item['full_name']) ?></strong><br><small class="muted"><?= e($item['employee_code']) ?> · <?= e($item['department']) ?></small></td><td><?= e($item['leave_type']) ?><br><small><?= e((string) $item['days']) ?> days</small></td><td><?= e(date('M j', strtotime($item['start_date']))) ?> - <?= e(date('M j, Y', strtotime($item['end_date']))) ?></td><td><?= e($item['reason']) ?></td><td><span class="status status-<?= e($item['status']) ?>"><?= e($item['status']) ?></span></td><td><?php if ($item['status'] === 'pending'): ?><form method="post" class="d-flex gap-1"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="id" value="<?= $item['id'] ?>"><input type="text" name="admin_remarks" placeholder="Optional remark" class="form-control form-control-sm"><button class="btn btn-primary btn-sm" name="status" value="approved">Approve</button><button class="btn btn-outline-dark btn-sm" name="status" value="rejected">Reject</button></form><?php else: ?><small class="muted"><?= e($item['admin_remarks'] ?: 'No remarks') ?></small><?php endif; ?></td></tr><?php endwhile; ?></tbody></table></section></div><?php require __DIR__ . '/../includes/footer.php'; ?>
